        setCurrentIndex(0);
        setUserAnswers({});
        setShowResult(false);
        setTimeLeft(30 * 60);
        setIsActive(true);
        setActiveTool('cursor');
        setModifiedParagraphs({});
    };

    const handleAnswerSelect = (questionId: string, answer: string) => {
        if (showResult && mode === 'practice') return; // Prevent changing in practice after check
        setUserAnswers(prev => ({
            ...prev,
            [questionId]: answer
        }));
    };

    const checkResult = () => {
        setShowResult(true);
    };

