                                onClick={(e) => handleEraser(e, idx)}
                                className={`text-slate-800 dark:text-slate-200 leading-relaxed text-justify 
                                    ${activeTool === 'highlight' ? 'cursor-text selection:bg-yellow-200 selection:text-black' : ''} 
